package com.example.legacy;

// 传统写法：对象自己创建并组装依赖（无 IoC）
interface UserRepository {
    String findName(long id);
}

class MySqlUserRepository implements UserRepository {
    @Override
    public String findName(long id) {
        // 假装在查 MySQL
        return "user-" + id;
    }
}

public class UserService {
    // 痛点1：依赖实现被硬编码，换 Redis 要改这里
    private final UserRepository repo = new MySqlUserRepository();

    public String displayName(long id) {
        return "用户:" + repo.findName(id);
    }

    public static void main(String[] args) {
        UserService service = new UserService();
        System.out.println(service.displayName(42));
    }
}

package com.example.ioc;

import java.util.HashMap;
import java.util.Map;

// IoC 写法：组件只声明依赖，创建与装配交给容器
interface UserRepository {
    String findName(long id);
}

class CachedUserRepository implements UserRepository {
    private final Map<Long, String> cache = new HashMap<>();

    @Override
    public String findName(long id) {
        return cache.computeIfAbsent(id, k -> "cached-" + k);
    }
}

class UserService {
    // 依赖从构造器「注入」，本类不知道具体实现是谁
    private final UserRepository repo;
    UserService(UserRepository repo) {
        this.repo = repo;
    }

    String displayName(long id) {
        return "用户:" + repo.findName(id);
    }
}

// 这个类扮演「IoC 容器」的角色：决定造什么、装给谁
public class IocDemo {
    public static void main(String[] args) {
        // 真实 Spring 中这一步由 ApplicationContext 自动完成
        UserRepository repo = new CachedUserRepository();
        UserService service = new UserService(repo);
        System.out.println(service.displayName(42));
    }
}
